class Animal:
    def speak(self):
        return "..."


class Dog(Animal):
    def speak(self):
        return "Гав"


class Cat(Animal):
    def speak(self):
        return "Мяу"


def chorus(kinds):
    classes = {"dog": Dog, "cat": Cat}
    return [classes.get(kind, Animal)().speak() for kind in kinds]

